#include "defines.hpp"

// include benchmark-specific definitions
#include "trmm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A: i x k  (M x M)
	// Layout: scalar ^ vector<'k'> ^ vector<'i'>
	//   -> dimensions: 'i' (row, outer), 'k' (col, inner, contiguous)
	// This is a row-major layout w.r.t. (i,k), but in the kernel we
	// access A[k][i], i.e. we treat A as transposed. In the optimized
	// kernel we iterate with k as the “row” and i as the “column”.
	// With this layout, A[k][i] is accessed with unit stride in the
	// innermost loop (dimension 'k' is inner and we map algorithmic
	// i to 'k'), which is cache‑friendly and vectorizable.
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B: i x j  (M x N)
	// Layout: scalar ^ vector<'j'> ^ vector<'i'>
	//   -> dimensions: 'i' (row, inner, contiguous), 'j' (col, outer)
	// This makes each column B[0..M-1][j] contiguous in memory, which
	// matches the access pattern B[k][j] and B[i][j] used in the kernel.
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	// A: i x k, square M x M
	// B: i x j, M x N

	alpha = (num_t)1.5;

	const int m_len = static_cast<int>(A | get_length<'i'>());
	const int n_len = static_cast<int>(B | get_length<'j'>());

	// Initialize A: unit lower-triangular
	// for (i = 0; i < m; i++) {
	//   for (j = 0; j < i; j++) A[i][j] = ((i + j) % m) / m;
	//   A[i][i] = 1.0;
	// }
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		int ii = static_cast<int>(i);
		int kk = static_cast<int>(k);

		if (kk < ii) {
			A[state] = (num_t)((ii + kk) % m_len) / (num_t)m_len;
		} else if (kk == ii) {
			A[state] = (num_t)1.0;
		}
		// For kk > ii we leave A[state] uninitialized, matching the C code
	});

	// Initialize B
	// for (i = 0; i < m; i++)
	//   for (j = 0; j < n; j++)
	//     B[i][j] = ((n + (i - j)) % n) / n;
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		int ii = static_cast<int>(i);
		int jj = static_cast<int>(j);

		B[state] = (num_t)(((n_len + (ii - jj)) % n_len)) / (num_t)n_len;
	});
}

// Main computational kernel
// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized kernel:
// -----------------
// We use an equivalent but more locality‑friendly traversal:
//
//   for (j = 0; j < N; ++j) {
//     for (k = 0; k < M; ++k) {
//       num_t Bkj = B[k][j];           // source row once per (k,j)
//       for (i = 0; i < k; ++i)
//         B[i][j] += A[k][i] * Bkj;   // accumulate into all i<k
//     }
//     for (i = 0; i < M; ++i)
//       B[i][j] *= alpha;             // scale after full reduction
//   }
//
// For each fixed (i,j), this performs the k‑updates in the *same order*
// k = i+1, i+2, ..., M-1 as the original code. The only change is the
// *schedule* in which different (i,j) are updated, which does not affect
// the result because there are no loop‑carried dependencies across j, and
// across i the value B[k][j] is always read before it is ever updated.
// Thus the floating‑point operation sequence for each B[i][j] is preserved.
//
// The benefits are:
//   * B[k][j] is loaded once per (k,j) and reused for all i<k instead of
//     being reloaded for every (i<k).
//   * A[k][i] and B[i][j] are both accessed with unit stride in the inner
//     i‑loop (due to the chosen layouts).
//   * We optionally tile the j‑dimension to improve cache behavior for
//     wide matrices. The tile size is a tunable constant.
//
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	const std::size_t m_len = A | get_length<'i'>(); // M
	const std::size_t n_len = B | get_length<'j'>(); // N

	// Tunable tile size for the j (column) dimension. Adjust this to better
	// fit the target cache hierarchy (e.g., L2/L3 cache size).
	constexpr std::size_t J_BLOCK = 64;

	#pragma scop
	// Tile the j-dimension manually; within each tile we still use Noarr
	// traversers to iterate over structure dimensions.
	for (std::size_t j_block_start = 0; j_block_start < n_len; j_block_start += J_BLOCK) {
		const std::size_t jb_width =
			(j_block_start + J_BLOCK <= n_len) ? J_BLOCK : (n_len - j_block_start);

		// View of B restricted to the current j-block:
		//   B_block has the same dimensions as B ('i', 'j'),
		//   but 'j' now runs over [0, jb_width).
		auto B_block = B ^ slice<'j'>(j_block_start, jb_width);

		// Iterate over columns (j) in the current block.
		traverser(B_block).template for_dims<'j'>([&](auto trav_j) {
			// trav_j has 'j' fixed, 'i' still varying.
			// We use its state as a base for constructing states with different i.
			auto base_state_j = trav_j.state();

			// Outer loop over k: this corresponds to the "source row" k
			// that contributes to all rows i < k in the current column.
			for (std::size_t k = 0; k < m_len; ++k) {
				// Source element B[k][j] (same for all i<k in this column).
				auto state_kj = base_state_j.template with<index_in<'i'>>(k);
				num_t Bkj = B_block[state_kj];

				// For k == 0 the inner loop would be empty.
				if (k == 0)
					continue;

				// Accumulate the contribution of row k into all rows i < k:
				//
				//   for i in [0, k):
				//     B[i][j] += A[k][i] * B[k][j];
				//
				// Layout considerations:
				//   * B has layout j_vec ^ i_vec, so 'i' is the inner,
				//     contiguous dimension. Varying i here walks B[i][j]
				//     with unit stride.
				//   * A has layout k_vec ^ i_vec, and we access A[k][i] as
				//       a_state = idx<'i','k'>(k, i)
				//     which maps algorithmic 'k' to dimension 'i' (outer)
				//     and algorithmic 'i' to dimension 'k' (inner). As i
				//     increases, the 'k' dimension index increases, so we
				//     walk A[k][i] with unit stride as well.
				for (std::size_t i = 0; i < k; ++i) {
					// Destination element B[i][j] in the current tile.
					auto state_ij = base_state_j.template with<index_in<'i'>>(i);

					// Triangular matrix element A[k][i]; note the intentional
					// transposition in the index mapping.
					auto a_state = idx<'i', 'k'>(k, i);

					B_block[state_ij] += A[a_state] * Bkj;
				}
			}

			// Finally, scale the entire column by alpha. This is done after
			// the k-loop to retain the original computation order for each
			// B[i][j]: first the reduction over k, then a single multiply.
			trav_j.for_each([&](auto state_ij) {
				B_block[state_ij] *= alpha;
			});
		});
	}
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;

	// set lengths for all dimensions used
	auto set_lengths = noarr::set_length<'i'>(m)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths); // M x M
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths); // M x N

	// initialize data
	init_array(alpha, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trmm(alpha, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE prevention / correctness check)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, B.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
