		for (std::size_t k = i + 1; k < m_len; ++k) {
			// Coefficient A[k][i]; note that A is laid out as (i x k),
			// but the algorithm accesses column-wise as A[k][i].
			num_t a_ki = A[ idx<'i', 'k'>(k, i) ];

