		} else if (kk == ii) {
			A[state] = (num_t)1.0;
		}
		// For kk > ii we leave A[state] uninitialized, matching the C code
	});

	// Initialize B
	// for (i = 0; i < m; i++)
	//   for (j = 0; j < n; j++)
	//     B[i][j] = ((n + (i - j)) % n) / n;
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		int ii = static_cast<int>(i);
		int jj = static_cast<int>(j);

		B[state] = (num_t)(((n_len + (ii - jj)) % n_len)) / (num_t)n_len;
	});
}

// Main computational kernel
// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized version:
// ------------------
// 1. Observe that B[k][j] is always read before row k is updated, so the
//    algorithm depends only on the original B (call it B0):
//       B[i][j] = alpha * ( B0[i][j]
//                           + sum_{k=i+1..M-1} A[k][i] * B0[k][j] )
// 2. This allows us to reorder the computation into an "outer-product" form:
//
//    for (k = 0; k < M; ++k)
//      for (i = 0; i < k; ++i)              // i < k
//        for (j = 0; j < N; ++j)
//          B[i][j] += A[k][i] * B[k][j];    // uses original B[k][j]
//
//    then a separate scaling:
//
//      for (i = 0; i < M; ++i)
//        for (j = 0; j < N; ++j)
//          B[i][j] *= alpha;
//
//    This is algebraically equivalent to the original code.
// 3. Data-locality improvements:
//    - For fixed (k, i), the inner j-loop updates entire rows i and k of B,
//      so B[i][*] and B[k][*] are traversed contiguously in memory.
//    - We load A[k][i] once per (k, i) and reuse it across the whole row.
// 4. Implementation with Noarr:
//    - We build a transposed *view* of A so that accessing A[k][i] becomes
//      a unit-stride access in the inner i-dimension of the view.
//    - All loop nests (over k, i, j) are expressed using Noarr traversers
//      and for_dims(), as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	// Transposed view of A:
	//   - Original A has dimensions ('i', 'k') with layout a_layout = k_vec ^ i_vec
	//   - We want to access A[k][i] frequently.
	//   - rename<'i','k','k','i'> swaps the dimension *names*:
	//       new 'i' := old 'k'
	//       new 'k' := old 'i'
	//     so A_T(i, k) == original A(k, i).
	auto A_T = A ^ noarr::rename<'i', 'k', 'k', 'i'>();

	// Traverser over the transposed A, hoisting 'k' so we iterate (k outer, i inner).
	auto trav_A = noarr::traverser(A_T).order(noarr::hoist<'k'>());

	// Traverser over B; we will repeatedly iterate only the 'j' dimension,
	// deriving row states ('i') manually via state arithmetic.
	auto trav_B = noarr::traverser(B);

	#pragma scop
	// Outer "k" loop: for each k = 0..M-1
	trav_A.template for_dims<'k'>([&](auto trav_k) {
		auto state_k = trav_k.state();
		std::size_t k = noarr::get_index<'k'>(state_k);

		// Inner "i" loop: for each i = 0..M-1 (we will filter to i < k)
		trav_k.template for_dims<'i'>([&](auto trav_ki) {
			auto state_ki = trav_ki.state();
			std::size_t i = noarr::get_index<'i'>(state_ki);

			// We only need the strict lower triangle (i < k).
			if (i >= k)
				return;

			// A_T[i, k] == original A[k, i]; load once and reuse across the j-loop.
			num_t a_ki = A_T[state_ki];

			// Innermost "j" loop over all columns:
			//   for (j = 0; j < N; ++j)
			//
			// We iterate j via a traverser over B, and derive the two row states
			// (i, j) and (k, j) using state arithmetic. This keeps j contiguous,
			// so B[i,*] and B[k,*] are streamed linearly in memory.
			trav_B.template for_dims<'j'>([&](auto trav_j) {
				auto state_j = trav_j.state(); // contains index in 'j'

				// Build full states for B[i][j] and B[k][j] by adding the row index.
				auto state_i_j = state_j + noarr::idx<'i'>(i);
				auto state_k_j = state_j + noarr::idx<'i'>(k);

				B[state_i_j] += a_ki * B[state_k_j];
			});
		});
