//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized version:
// - We still iterate rows of B by 'i' using a traverser.
// - For each row i, we iterate k from i+1 to M-1 and *reuse* A[k][i]
//   across the whole row B[i,*], i.e. we pull the j-loop inside the k-loop:
//
//   for i
//     for k = i+1..M-1
//       aik = A[k][i];
//       for all j: B[i][j] += aik * B[k][j];
//     for all j: B[i][j] *= alpha;
//
//   For each (i,j) the sequence of updates in k is identical to the
//   reference code, so floating‑point semantics are preserved (same order
//   of additions for each output element). This reordering improves:
//     - locality on A: A[k][i] is loaded once per (i,k) instead of per (i,k,j)
//     - locality on B: B[k][*] is read as a contiguous row inside the
//       inner j-loop.
//
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	const std::size_t m_len = A | get_length<'i'>();

	#pragma scop
	// Outer loop over rows 'i' of B, via traverser::for_dims.
	traverser(B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, iterates over remaining dimension 'j'
		const std::size_t i = static_cast<std::size_t>(get_index<'i'>(trav_i.state()));

		// Triangular matrix-matrix multiply:
		// for k = i+1 .. m_len-1: B[i,*] += A[k][i] * B[k,*]
		for (std::size_t k = i + 1; k < m_len; ++k) {
			// A[k][i] -> A at (i = k, k = i)
			const num_t aik = A[noarr::idx<'i', 'k'>(k, i)];

			// Update the whole row B[i,*] using this aik.
			// trav_i.for_each walks all columns 'j' for the fixed row 'i'.
			trav_i.for_each([&](auto s_ij) {
				const auto j = get_index<'j'>(s_ij);

				// B[k][j] -> B at (i = k, j = j)
				const auto s_kj = noarr::idx<'i', 'j'>(k, j);

				B[s_ij] += aik * B[s_kj];
			});
		}

		// Scale row i: B[i,*] *= alpha
		trav_i.for_each([&](auto s_ij) {
			B[s_ij] *= alpha;
		});
	});
	#pragma endscop
}

