namespace {

// Base vector proto-structures for dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// Simple tunable blocking factor for the k-loop in the kernel.
// Can be adjusted to better fit the cache hierarchy of the target CPU.
constexpr std::size_t TRMM_K_BLOCK = 64;

struct tuning {
	// A: i x k (M x M)
	// Layout is k (inner, contiguous) inside i (outer): scalar ^ k_vec ^ i_vec
	// This corresponds to a row-major layout A[i][k].
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B: i x j (M x N)
	// Layout is j (inner, contiguous) inside i (outer): scalar ^ j_vec ^ i_vec
	// This corresponds to a row-major layout B[i][j].
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(num_t &alpha, auto A, auto B) {
	using namespace noarr;

	// A: i x k, square M x M
	// B: i x j, M x N

	alpha = (num_t)1.5;

	const int m_len = static_cast<int>(A | get_length<'i'>());
	const int n_len = static_cast<int>(B | get_length<'j'>());

	// Initialize A: unit lower-triangular
	// for (i = 0; i < m; i++) {
	//   for (k = 0; k < i; k++) A[i][k] = ((i + k) % m) / m;
	//   A[i][i] = 1.0;
	// }
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		int ii = static_cast<int>(i);
		int kk = static_cast<int>(k);

		if (kk < ii) {
			A[state] = (num_t)((ii + kk) % m_len) / (num_t)m_len;
		} else if (kk == ii) {
			A[state] = (num_t)1.0;
		}
		// For kk > ii we leave A[state] uninitialized, matching the C code
	});

	// Initialize B
	// for (i = 0; i < m; i++)
	//   for (j = 0; j < n; j++)
	//     B[i][j] = ((n + (i - j)) % n) / n;
	traverser(B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		int ii = static_cast<int>(i);
		int jj = static_cast<int>(j);

		B[state] = (num_t)(((n_len + (ii - jj)) % n_len)) / (num_t)n_len;
	});
}

// Main computational kernel
// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized version below keeps the same mathematical operation:
//   B_out = alpha * (L^T * B_in),
// where L is the unit lower-triangular matrix stored in A.
// We:
//   1) Compute the triangular multiplication B := B + L^T * B
//      using a loop order that improves data locality:
//        i (row being updated), then k (contributing row), then j (columns).
//      This reduces the number of loads of A[k][i] from O(M^2 N) to O(M^2)
//      and keeps the innermost loop over j, which is contiguous in memory
//      for both B[i][j] and B[k][j].
//   2) Apply the scaling B[i][j] *= alpha in a separate pass.
//      This is equivalent to the original per-element scaling because
//      multiplication by a scalar commutes with the triangular update.
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	const std::size_t m_len = A | get_length<'i'>();

	#pragma scop
	// Phase 1: B[i][j] += sum_{k>i} A[k][i] * B[k][j]
	// We iterate rows of B via a traverser over dimension 'i'.
	traverser(B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, remaining dimension is 'j'
		const auto state_i = trav_i.state();
		const std::size_t i = get_index<'i'>(state_i);

		// Block the k-loop to allow tuning for cache hierarchies.
		// TRMM_K_BLOCK can be adjusted without changing semantics.
		for (std::size_t k_block = i + 1; k_block < m_len; k_block += TRMM_K_BLOCK) {
			std::size_t k_block_end = k_block + TRMM_K_BLOCK;
			if (k_block_end > m_len)
				k_block_end = m_len;

			for (std::size_t k = k_block; k < k_block_end; ++k) {
				// A[k][i] -> A at (i = k, k = i) in our layout
				const auto a_state = noarr::idx<'i', 'k'>(k, i);
				const num_t a_ki = A[a_state]; // loaded once per (i,k)

				// For this (i,k) pair, update the whole row i across all j.
				// trav_i.for_each iterates contiguous 'j' for the fixed 'i'.
				trav_i.for_each([&](auto state_ij) {
					const std::size_t j = get_index<'j'>(state_ij);

					// B[k][j] -> B at (i = k, j = j)
					const auto b_kj_state = noarr::idx<'i', 'j'>(k, j);

					B[state_ij] += a_ki * B[b_kj_state];
				});
			}
		}
	});

	// Phase 2: scale B by alpha
	// Equivalent to the original per-element scaling after the inner k-loop.
	traverser(B).for_each([=](auto state) {
		B[state] *= alpha;
	});
	#pragma endscop
}

} // namespace

